<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/functions.php';
require_login();
$type = (string)($_GET['type'] ?? '');
$id = (int)($_GET['id'] ?? 0);
$allowed = ['patient'=>'patients','bill'=>'bills','prescription'=>'prescriptions'];
if (!isset($allowed[$type]) || $id < 1) { http_response_code(404); exit('Print record not found.'); }
require_access($allowed[$type]);
$record = null;
if ($type === 'patient') {
    $stmt = $pdo->prepare('SELECT p.*,d.name AS department_name,doc.name AS doctor_name FROM patients p LEFT JOIN departments d ON d.id=p.department_id LEFT JOIN doctors doc ON doc.id=p.doctor_id WHERE p.id=?');
    $stmt->execute([$id]); $record=$stmt->fetch();
} elseif ($type === 'bill') {
    $stmt = $pdo->prepare('SELECT b.*,p.name AS patient_name,p.patient_code,p.phone,p.address FROM bills b JOIN patients p ON p.id=b.patient_id WHERE b.id=?');
    $stmt->execute([$id]); $record=$stmt->fetch();
} else {
    $stmt = $pdo->prepare('SELECT pr.*,p.name AS patient_name,p.patient_code,p.age,p.gender,doc.name AS doctor_name,doc.qualification,dp.name AS department_name FROM prescriptions pr JOIN patients p ON p.id=pr.patient_id JOIN doctors doc ON doc.id=pr.doctor_id LEFT JOIN departments dp ON dp.id=doc.department_id WHERE pr.id=?');
    $stmt->execute([$id]); $record=$stmt->fetch();
}
if (!$record) { http_response_code(404); exit('Record not found.'); }
$items=[];
if ($type==='prescription') { $s=$pdo->prepare('SELECT * FROM prescription_items WHERE prescription_id=? ORDER BY id'); $s->execute([$id]); $items=$s->fetchAll(); }
$payments=[];
if ($type==='bill') { $s=$pdo->prepare('SELECT * FROM payments WHERE bill_id=? ORDER BY payment_date'); $s->execute([$id]); $payments=$s->fetchAll(); }
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Print <?= e(ucfirst($type)) ?> · <?= e(APP_NAME) ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f2f5fa;color:#1b2d45;font-family:Arial,sans-serif}.paper{max-width:850px;margin:35px auto;background:#fff;padding:48px;box-shadow:0 12px 40px #2036541a;border-radius:12px}.brand{font-size:24px;font-weight:800;color:#135b9d}.sub{color:#64758b}.line{border-top:2px solid #1b79b8;margin:22px 0}.label{color:#728197;font-size:12px;text-transform:uppercase;letter-spacing:1px}.value{font-weight:600}.signature{margin-top:65px;display:flex;justify-content:space-between}@media print{body{background:#fff}.paper{box-shadow:none;margin:0 auto;padding:20px;max-width:none}.print-actions{display:none!important}}</style></head><body><div class="paper"><div class="d-flex justify-content-between align-items-start"><div><div class="brand"><i class="fa-solid fa-heart-pulse"></i> VIKRAM REDDY HOSPITAL</div><div class="sub">Multi-specialty healthcare · Warangal, Telangana</div></div><div class="text-end"><div class="label"><?= e(strtoupper($type)) ?> DOCUMENT</div><div class="value"><?= e($record[$type==='patient'?'patient_code':($type==='bill'?'bill_code':'prescription_code')]) ?></div><div class="sub">Printed <?= date('d M Y, h:i A') ?></div></div></div><div class="line"></div>
<?php if($type==='patient'): ?><h3 class="mb-4">Patient information</h3><div class="row g-4"><div class="col-6"><div class="label">Patient name</div><div class="value"><?= e($record['name']) ?></div></div><div class="col-6"><div class="label">Patient ID</div><div class="value"><?= e($record['patient_code']) ?></div></div><div class="col-4"><div class="label">Age / Gender</div><div class="value"><?= e($record['age']??'—') ?> / <?= e($record['gender']??'—') ?></div></div><div class="col-4"><div class="label">Blood group</div><div class="value"><?= e($record['blood_group']) ?></div></div><div class="col-4"><div class="label">Registration date</div><div class="value"><?= e($record['registration_date']) ?></div></div><div class="col-6"><div class="label">Phone</div><div class="value"><?= e($record['phone']) ?></div></div><div class="col-6"><div class="label">Email</div><div class="value"><?= e($record['email']??'—') ?></div></div><div class="col-12"><div class="label">Address</div><div class="value"><?= nl2br(e($record['address']??'—')) ?></div></div><div class="col-6"><div class="label">Assigned doctor</div><div class="value"><?= e($record['doctor_name']??'—') ?></div></div><div class="col-6"><div class="label">Department</div><div class="value"><?= e($record['department_name']??'—') ?></div></div><div class="col-12"><div class="label">Medical history</div><div class="value"><?= nl2br(e($record['medical_history']??'—')) ?></div></div><div class="col-12"><div class="label">Allergies</div><div class="value"><?= nl2br(e($record['allergies']??'—')) ?></div></div></div>
<?php elseif($type==='bill'): ?><h3 class="mb-4">Patient invoice</h3><div class="row mb-4"><div class="col-6"><div class="label">Bill to</div><div class="value"><?= e($record['patient_name']) ?></div><div><?= e($record['patient_code']) ?></div><div><?= e($record['phone']) ?></div><div><?= e($record['address']??'') ?></div></div><div class="col-6 text-end"><div class="label">Invoice date</div><div class="value"><?= e($record['bill_date']) ?></div><div class="label mt-2">Category</div><div class="value"><?= e($record['category']) ?></div></div></div><table class="table"><thead><tr><th>Description</th><th class="text-end">Amount</th></tr></thead><tbody><tr><td><?= e($record['description']?:$record['category']) ?></td><td class="text-end"><?= money($record['subtotal']) ?></td></tr><tr><td>Discount</td><td class="text-end">- <?= money($record['discount']) ?></td></tr><tr><td>Tax</td><td class="text-end"><?= money($record['tax']) ?></td></tr></tbody><tfoot><tr><th>Total</th><th class="text-end"><?= money($record['total_amount']) ?></th></tr><tr><td>Paid</td><td class="text-end"><?= money($record['paid_amount']) ?></td></tr><tr><th>Balance due</th><th class="text-end"><?= money($record['balance']) ?></th></tr></tfoot></table><h5 class="mt-4">Payment history</h5><table class="table table-sm"><thead><tr><th>Receipt</th><th>Date</th><th>Method</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><td><?= e($payment['receipt_code']) ?></td><td><?= e($payment['payment_date']) ?></td><td><?= e($payment['payment_method']) ?></td><td class="text-end"><?= money($payment['amount']) ?></td></tr><?php endforeach; ?></tbody></table>
<?php else: ?><h3 class="mb-4">Medical prescription</h3><div class="row mb-4"><div class="col-6"><div class="label">Patient</div><div class="value"><?= e($record['patient_name']) ?></div><div><?= e($record['patient_code']) ?> · <?= e($record['age']??'') ?> years · <?= e($record['gender']??'') ?></div></div><div class="col-6 text-end"><div class="label">Prescribed on</div><div class="value"><?= e($record['prescribed_at']) ?></div><div class="label mt-2">Doctor</div><div class="value"><?= e($record['doctor_name']) ?></div><div><?= e($record['qualification']??'') ?></div></div></div><div class="mb-3"><div class="label">Diagnosis</div><div class="value"><?= nl2br(e($record['diagnosis'])) ?></div></div><h5 class="mt-4">Medicines</h5><table class="table"><thead><tr><th>Medicine</th><th>Dosage</th><th>Frequency</th><th>Duration</th><th>Qty</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= e($item['medicine_name']) ?></td><td><?= e($item['dosage']) ?></td><td><?= e($item['frequency']) ?></td><td><?= e($item['duration']) ?></td><td><?= (int)$item['quantity'] ?></td></tr><?php endforeach; ?></tbody></table><div class="mt-4"><div class="label">Instructions</div><div class="value"><?= nl2br(e($record['instructions']??'—')) ?></div></div><?php endif; ?>
<div class="signature"><div><div style="border-top:1px solid #9aa9bb;width:180px;padding-top:8px">Patient / Guardian</div></div><div><div style="border-top:1px solid #9aa9bb;width:180px;padding-top:8px">Authorized signature</div></div></div><div class="line"></div><div class="text-center sub">This is a computer-generated document from Vikram Reddy Hospital. Keep it confidential.</div><div class="text-center mt-4 print-actions"><button class="btn btn-primary" onclick="window.print()"><i class="fa-solid fa-print me-2"></i>Print document</button> <button class="btn btn-outline-secondary" onclick="window.close()">Close</button></div></div></body></html>
